<?php require_once __DIR__.'/includes/bootstrap.php';require_role(['admin']);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$role=$_POST['role']??'member';$active=isset($_POST['is_active'])?1:0;if(!in_array($role,['admin','librarian','member'],true)){flash('error','Invalid role.');redirect('users.php');}if($id===(int)current_user()['id']&&(!$active||$role!=='admin')){flash('error','You cannot deactivate or demote yourself.');redirect('users.php');}$s=$conn->prepare('UPDATE users SET role=?,is_active=? WHERE id=?');$s->bind_param('sii',$role,$active,$id);$s->execute();log_activity($conn,(int)current_user()['id'],'user_updated','User ID '.$id.' role '.$role);flash('success','User updated. Log out and back in for changed role to take effect.');redirect('users.php');}$rows=$conn->query('SELECT id,full_name,email,role,email_verified,is_active,created_at FROM users ORDER BY id DESC');page_header('Users');?><div class="page-heading"><div><p class="eyebrow">ADMINISTRATION</p><h1>User accounts</h1><p class="muted">Roles are enforced on the server, not only hidden in the interface.</p></div></div><div class="table-wrap panel"><table><thead><tr><th>User</th><th>Verified</th><th>Role / status</th><th>Save</th></tr></thead><tbody><?php while($u=$rows->fetch_assoc()):?><tr><td><strong><?=e($u['full_name'])?></strong><div class="muted small"><?=e($u['email'])?></div></td><td><?=$u['email_verified']?'Yes':'No'?></td><td><form id="u<?=$u['id']?>" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="role"><?php foreach(['admin'=>'Administrator','librarian'=>'Librarian / Approver','member'=>'Student / Member'] as $k=>$v):?><option value="<?=$k?>" <?=$u['role']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><label class="check"><input type="checkbox" name="is_active" <?=$u['is_active']?'checked':''?>> Active</label></form></td><td><button class="btn small-btn" form="u<?=$u['id']?>">Save</button></td></tr><?php endwhile;?></tbody></table></div><?php page_footer();?>